import heapq

def match(orders):
    trades = []
    buy_heap = []   # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq'}
    seq_counter = 0

    def prune(heap):
        while heap:
            price, seq, oid = heap[0]
            if oid not in book or book[oid]['qty'] <= 0:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['qty'] > 0:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        if side == 'buy':
            opp_heap = sell_heap
            while remaining > 0:
                prune(opp_heap)
                if not opp_heap:
                    break
                p, s, oid2 = opp_heap[0]
                if typ != 'market' and p > price:
                    break
                o2 = book[oid2]
                trade_qty = min(remaining, o2['qty'])
                trades.append([oid, oid2, p, trade_qty])
                remaining -= trade_qty
                o2['qty'] -= trade_qty
                if o2['qty'] == 0:
                    heapq.heappop(opp_heap)
                    del book[oid2]
        else:
            opp_heap = buy_heap
            while remaining > 0:
                prune(opp_heap)
                if not opp_heap:
                    break
                negp, s, oid2 = opp_heap[0]
                p = -negp
                if typ != 'market' and p < price:
                    break
                o2 = book[oid2]
                trade_qty = min(remaining, o2['qty'])
                trades.append([oid2, oid, p, trade_qty])
                remaining -= trade_qty
                o2['qty'] -= trade_qty
                if o2['qty'] == 0:
                    heapq.heappop(opp_heap)
                    del book[oid2]

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': my_seq}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, my_seq, oid))
            else:
                heapq.heappush(sell_heap, (price, my_seq, oid))

    return trades

